WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, island_id, MAX(started_at) AS ended_at, SORT_ARRAY(COLLECT_SET(device)) AS device_list, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst, COUNT(*) FILTER (WHERE country = 'TH') AS th_rows, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst_2 FROM sessions_sessions GROUP BY 1, 2
